impl Document {
    pub(crate) fn compare_td_event_com(
        &self,
        other: &Document,
        a: &TDEventCom,
        b: &TDEventCom,
        path: &str,
    ) -> Result<(), String> {
        self.compare_timing_description_event(other, a.base(), b.base(), path)?;
        if a.get_ecu_instance_ref() != b.get_ecu_instance_ref() {
            return Err(format!("{path}: ECU_INSTANCE_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_cycle_start(
        &self,
        other: &Document,
        a: &TDEventCycleStart,
        b: &TDEventCycleStart,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_com(other, a.base(), b.base(), path)?;
        if a.get_cycle_repetition() != b.get_cycle_repetition() {
            return Err(format!("{path}: CYCLE_REPETITION mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_fr_cluster_cycle_start(
        &self,
        other: &Document,
        a: &TDEventFrClusterCycleStart,
        b: &TDEventFrClusterCycleStart,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_cycle_start(other, a.base(), b.base(), path)?;
        if a.get_fr_cluster_ref() != b.get_fr_cluster_ref() {
            return Err(format!("{path}: FR_CLUSTER_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_frame(
        &self,
        other: &Document,
        a: &TDEventFrame,
        b: &TDEventFrame,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_com(other, a.base(), b.base(), path)?;
        if a.get_frame_ref() != b.get_frame_ref() {
            return Err(format!("{path}: FRAME_REF mismatch"));
        }
        if a.get_physical_channel_ref() != b.get_physical_channel_ref() {
            return Err(format!("{path}: PHYSICAL_CHANNEL_REF mismatch"));
        }
        if a.get_td_event_type() != b.get_td_event_type() {
            return Err(format!("{path}: TD_EVENT_TYPE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_frame_ethernet(
        &self,
        other: &Document,
        a: &TDEventFrameEthernet,
        b: &TDEventFrameEthernet,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_com(other, a.base(), b.base(), path)?;
        if a.get_static_socket_connection_ref() != b.get_static_socket_connection_ref() {
            return Err(format!("{path}: STATIC_SOCKET_CONNECTION_REF mismatch"));
        }
        if a.get_td_event_type() != b.get_td_event_type() {
            return Err(format!("{path}: TD_EVENT_TYPE mismatch"));
        }
        let list_a = a.get_td_header_id_filter();
        let list_b = b.get_td_header_id_filter();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TD_HEADER_ID_FILTER length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.td_header_id_ranges.get(*x).ok_or_else(|| {
                format!("{path}.TD_HEADER_ID_FILTER[{index}]: id not found in own arena")
            })?;
            let y = other.td_header_id_ranges.get(*y).ok_or_else(|| {
                format!("{path}.TD_HEADER_ID_FILTER[{index}]: id not found in other arena")
            })?;
            self.compare_td_header_id_range(
                other,
                x,
                y,
                &format!("{path}.TD_HEADER_ID_FILTER[{index}]"),
            )?;
        }
        let list_a = a.get_td_pdu_triggering_filter_refs();
        let list_b = b.get_td_pdu_triggering_filter_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: TD_PDU_TRIGGERING_FILTER_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!(
                    "{path}.TD_PDU_TRIGGERING_FILTER_REFS[{index}] mismatch"
                ));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_i_pdu(
        &self,
        other: &Document,
        a: &TDEventIPdu,
        b: &TDEventIPdu,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_com(other, a.base(), b.base(), path)?;
        if a.get_i_pdu_ref() != b.get_i_pdu_ref() {
            return Err(format!("{path}: I_PDU_REF mismatch"));
        }
        if a.get_physical_channel_ref() != b.get_physical_channel_ref() {
            return Err(format!("{path}: PHYSICAL_CHANNEL_REF mismatch"));
        }
        if a.get_td_event_type() != b.get_td_event_type() {
            return Err(format!("{path}: TD_EVENT_TYPE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_i_signal(
        &self,
        other: &Document,
        a: &TDEventISignal,
        b: &TDEventISignal,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_com(other, a.base(), b.base(), path)?;
        if a.get_i_signal_ref() != b.get_i_signal_ref() {
            return Err(format!("{path}: I_SIGNAL_REF mismatch"));
        }
        if a.get_physical_channel_ref() != b.get_physical_channel_ref() {
            return Err(format!("{path}: PHYSICAL_CHANNEL_REF mismatch"));
        }
        if a.get_td_event_type() != b.get_td_event_type() {
            return Err(format!("{path}: TD_EVENT_TYPE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_event_tt_can_cycle_start(
        &self,
        other: &Document,
        a: &TDEventTTCanCycleStart,
        b: &TDEventTTCanCycleStart,
        path: &str,
    ) -> Result<(), String> {
        self.compare_td_event_cycle_start(other, a.base(), b.base(), path)?;
        if a.get_tt_can_cluster_ref() != b.get_tt_can_cluster_ref() {
            return Err(format!("{path}: TT_CAN_CLUSTER_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_td_header_id_range(
        &self,
        _other: &Document,
        a: &TDHeaderIdRange,
        b: &TDHeaderIdRange,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_max_header_id() != b.get_max_header_id() {
            return Err(format!("{path}: MAX_HEADER_ID mismatch"));
        }
        if a.get_min_header_id() != b.get_min_header_id() {
            return Err(format!("{path}: MIN_HEADER_ID mismatch"));
        }
        Ok(())
    }
}
